from __future__ import annotations
from pathlib import Path
import json

def generate_hyperframes_project(out_dir, brief, style, beats):
    out=Path(out_dir);out.mkdir(parents=True,exist_ok=True);duration=float(brief['duration']);w,h=1080,1920
    html=f'''<!doctype html><html><head><meta charset="utf-8"><style>html,body{{margin:0;width:{w}px;height:{h}px;overflow:hidden}}body{{background:{style['palette'][0]};color:{style['palette'][1]};}}#comp{{position:relative;width:{w}px;height:{h}px;overflow:hidden;font-family:Arial,sans-serif}}.grid{{position:absolute;inset:64px;background-image:linear-gradient(rgba(0,0,0,.12) 1px,transparent 1px),linear-gradient(90deg,rgba(0,0,0,.12) 1px,transparent 1px);background-size:120px 120px}}.title{{position:absolute;left:80px;right:80px;top:780px;text-align:center;font-family:Georgia,serif;font-size:96px}}.coin{{position:absolute;width:560px;height:560px;border-radius:50%;left:-40px;top:120px;background:radial-gradient(circle at 35% 30%,#f5f1e6,#9d998f 55%,#423f3a 100%);box-shadow:0 40px 60px rgba(0,0,0,.2)}}</style></head><body><div id="comp" data-composition-id="motion-os" data-start="0" data-duration="{duration}" data-track-index="0" data-width="{w}" data-height="{h}"><div class="grid"></div><div class="coin"></div><div class="title">{brief['headline']}</div></div><script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script><script>window.__timelines=window.__timelines||{{}};const tl=gsap.timeline({{paused:true}});tl.from('.grid',{{opacity:0,scale:1.08,duration:1,ease:'power3.out'}},0).from('.coin',{{x:-260,y:-160,scale:.35,rotation:-28,opacity:0,duration:1.2,ease:'back.out(1.2)'}},.2).from('.title',{{y:80,opacity:0,duration:.7,ease:'expo.out'}},1.2).to('.coin',{{x:620,y:900,scale:2.4,rotation:35,duration:.8,ease:'expo.inOut'}},4.2);window.__timelines['motion-os']=tl;</script></body></html>'''
    (out/'index.html').write_text(html,encoding='utf-8');(out/'DESIGN.md').write_text(f"# Generated by MOTION.OS\n\nStyle: {style['style_id']}\nPalette: {style['palette']}\nTypography: {style['type']}\n",encoding='utf-8');(out/'motion_graph_slice.json').write_text(json.dumps({'brief':brief,'style':style,'beats':beats},indent=2),encoding='utf-8');return out

def generate_remotion_project(out_dir, brief, style, beats):
    out=Path(out_dir);src=out/'src';src.mkdir(parents=True,exist_ok=True);fps=int(brief['fps']);frames=round(float(brief['duration'])*fps)
    (out/'package.json').write_text(json.dumps({'name':'motion-os-generated','private':True,'scripts':{'start':'remotion studio','render':'remotion render MotionOS out.mp4'},'dependencies':{'@remotion/cli':'^4.0.0','remotion':'^4.0.0','react':'^19.0.0','react-dom':'^19.0.0'}},indent=2),encoding='utf-8');(src/'index.ts').write_text("import {registerRoot} from 'remotion'; import {Root} from './Root'; registerRoot(Root);\n",encoding='utf-8');(src/'Root.tsx').write_text(f'''import React from 'react';import {{Composition}} from 'remotion';import {{MotionOS}} from './MotionOS';export const Root=()=> <Composition id="MotionOS" component={{MotionOS}} durationInFrames={frames} fps={fps} width={{1080}} height={{1920}}/>;''',encoding='utf-8');(src/'MotionOS.tsx').write_text(f'''import React from 'react';import {{AbsoluteFill,Easing,interpolate,useCurrentFrame}} from 'remotion';export const MotionOS=()=>{{const f=useCurrentFrame();const opacity=interpolate(f,[0,{fps}],[0,1],{{extrapolateRight:'clamp',easing:Easing.bezier(.16,1,.3,1)}});const y=interpolate(f,[0,{fps}],[90,0],{{extrapolateRight:'clamp'}});return <AbsoluteFill style={{{{backgroundColor:'{style['palette'][0]}',color:'{style['palette'][1]}',display:'flex',alignItems:'center',justifyContent:'center'}}}}><div style={{{{fontFamily:'Georgia,serif',fontSize:96,opacity,translate:`0 ${{y}}px`,textAlign:'center',maxWidth:920}}}}>{brief['headline']}</div></AbsoluteFill>}};''',encoding='utf-8');(out/'motion_graph_slice.json').write_text(json.dumps({'brief':brief,'style':style,'beats':beats},indent=2),encoding='utf-8');return out
